import json, math
d=json.load(open('/Users/sbr/.claude/projects/-Users-sbr-gds-agent-benchmarks/da4aad77-1676-42fa-ba30-215d4e110fd2/tool-results/mcp-gds-agent-read_neo4j_cypher-1794272036330.txt'))
adj={}
for r in d:
    adj.setdefault(r['a'],set()).add(r['b']); adj.setdefault(r['b'],set()).add(r['a'])
# components
seen=set();comps=[]
for n in adj:
    if n in seen: continue
    st=[n];c=set([n]);seen.add(n)
    while st:
        u=st.pop()
        for v in adj[u]:
            if v not in seen: seen.add(v);c.add(v);st.append(v)
    comps.append(len(c))
print("components",sorted(comps,reverse=True))
x={n:1.0 for n in adj}
for it in range(2000):
    y={n:sum(x[m] for m in adj[n]) for n in adj}
    norm=math.sqrt(sum(v*v for v in y.values()))
    y={n:v/norm for n,v in y.items()}
    diff=sum(abs(y[n]-x[n]) for n in adj); x=y
    if diff<1e-12: break
print(it)
for n in ["Canada Water","Bank","King's Cross St. Pancras","Baker Street","Oxford Circus","Green Park","Waterloo","Liverpool Street","Canary Wharf","Bermondsey"]:
    print(n, round(x.get(n,float('nan')),5))
print(sorted(x.items(),key=lambda kv:-kv[1])[:5])
EOF

