cd /tmp && python3 -I - << 'EOF'
from collections import deque, defaultdict
adj = defaultdict(set)
for e in open('/tmp/bc_check/edges.txt').read().strip().split(';'):
    if not e: continue
    a,b,c = e.split('|')
    adj[a].add(b); adj[b].add(a)
nodes = list(adj)
bc = defaultdict(float)
for s in nodes:  # Brandes
    S=[]; P=defaultdict(list); sigma=defaultdict(int); sigma[s]=1; d={s:0}; Q=deque([s])
    while Q:
        v=Q.popleft(); S.append(v)
        for w in adj[v]:
            if w not in d: d[w]=d[v]+1; Q.append(w)
            if d[w]==d[v]+1: sigma[w]+=sigma[v]; P[w].append(v)
    delta=defaultdict(float)
    while S:
        w=S.pop()
        for v in P[w]: delta[v]+=sigma[v]/sigma[w]*(1+delta[w])
        if w!=s: bc[w]+=delta[w]
print(len(nodes), {k: round(bc[k]/2,4) for k in ['Westminster','Waterloo']})
EOF

cd /tmp && python3 -I - << 'EOF'
from collections import deque, defaultdict
adj = defaultdict(lambda: defaultdict(int))
for e in open('/tmp/bc_check/edges.txt').read().strip().split(';'):
    if not e: continue
    a,b,c = e.split('|')
    adj[a][b]+=int(c); adj[b][a]+=int(c)
nodes = list(adj)
bc = defaultdict(float)
for s in nodes:
    S=[]; P=defaultdict(list); sigma=defaultdict(int); sigma[s]=1; d={s:0}; Q=deque([s])
    while Q:
        v=Q.popleft(); S.append(v)
        for w,m in adj[v].items():
            if w not in d: d[w]=d[v]+1; Q.append(w)
            if d[w]==d[v]+1: sigma[w]+=sigma[v]*m; P[w].append((v,m))
    delta=defaultdict(float)
    while S:
        w=S.pop()
        for v,m in P[w]: delta[v]+=m*sigma[v]/sigma[w]*(1+delta[w])
        if w!=s: bc[w]+=delta[w]
print({k: round(bc[k]/2,4) for k in ['Westminster','Waterloo']})
EOF

