parameters.cypher_query:
MATCH (n:UndergroundStation)-[r:LINK]->(m:UndergroundStation)
RETURN gds.graph.project($graph_name, n, m, {
  sourceNodeLabels: labels(n), targetNodeLabels: labels(m),
  sourceNodeProperties: {latitude: n.latitude, longitude: n.longitude},
  targetNodeProperties: {latitude: m.latitude, longitude: m.longitude},
  relationshipType: type(r),
  relationshipProperties: {distance: toFloat(r.distance), time: toFloat(r.time)}
}, { undirectedRelationshipTypes: ['LINK'] })

